+fn flatten_would_affect_implicated<'input, 'arena>(
+    element: &Element<'input, 'arena>,
+    implicated: &Implicated<'input, 'arena>,
+) -> bool {
+    if implicated.contains(element) {
+        log::debug!("collapse_groups: not flattening: implicated group");
+        return true;
+    }
+    if element.children_iter().any(|child| implicated.contains(&child)) {
+        log::debug!("collapse_groups: not flattening: implicated child");
+        return true;
+    }
+    // Removing `element` shifts all following siblings, so an implicated
+    // following sibling may stop matching structural pseudo-classes.
+    let mut sibling = element.next_element_sibling();
+    while let Some(s) = sibling {
+        if implicated.contains(&s) {
+            log::debug!("collapse_groups: not flattening: implicated next sibling");
+            return true;
+        }
+        sibling = s.next_element_sibling();
+    }
+    false
+}
